    closed_at BIGINT,
    close_reason TEXT,
    -- правила v1 §4: машина состояний контекста (state сохранён для
    -- совместимости; awaiting_h1→awaiting_initial_confirmation,
    -- confirmed→context_active, терминальные значения без изменений)
