    first_test_at BIGINT,
    validity TEXT NOT NULL DEFAULT 'fresh',  -- fresh | tested | invalid
    -- ТЗ «Единый движок» §3/§4: максимум глубины тестов за всю историю и
    -- глубочайший экстремум (точные сравнения порога 90% без epsilon)
    max_test_depth DOUBLE PRECISION NOT NULL DEFAULT 0,
    test_extreme DOUBLE PRECISION,
    source TEXT NOT NULL DEFAULT 'auto',
    rule_version TEXT NOT NULL DEFAULT 'ltf-0.2',
    evidence TEXT NOT NULL DEFAULT '{}',
    UNIQUE (instrument_id, type, direction, lower, upper, formed_at, movement_id)
);

CREATE TABLE IF NOT EXISTS ltf_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    observation_id BIGINT NOT NULL ,
    scenario_id BIGINT,
    kind TEXT NOT NULL,
    payload TEXT NOT NULL DEFAULT '{}',
    occurred_at BIGINT NOT NULL,
    detected_at BIGINT NOT NULL,
    dedupe_key TEXT NOT NULL,
    delivered BIGINT NOT NULL DEFAULT 0,
    delayed BIGINT NOT NULL DEFAULT 0,
    -- F01/A01: происхождение события (live|catchup|replay|unknown) и лаг
    -- обнаружения относительно закрытия свечи; delayed = processing_mode != 'live'
    processing_mode TEXT NOT NULL DEFAULT 'unknown',
    detection_lag_ms BIGINT NOT NULL DEFAULT 0,
    -- ТЗ 07.10.2026 §7: состояние графика события отдельно от состояния
    -- доставки текста (none | sent | failed + число попыток)
    chart_state TEXT NOT NULL DEFAULT 'none',
    chart_attempts BIGINT NOT NULL DEFAULT 0,
    UNIQUE (dedupe_key)
);

CREATE TABLE IF NOT EXISTS ltf_liquidity_test (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entry_zone_id BIGINT NOT NULL ,
    scenario_id BIGINT NOT NULL ,
    level DOUBLE PRECISION NOT NULL,
    touch_at BIGINT NOT NULL,
    candle_open_time BIGINT NOT NULL,
    state TEXT NOT NULL DEFAULT 'awaiting_close',
    close_price DOUBLE PRECISION,
    sweep_at BIGINT,
    resolved_at BIGINT
);

CREATE TABLE IF NOT EXISTS ltf_movement (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL ,
    start_pivot_id BIGINT NOT NULL,
    end_pivot_id BIGINT NOT NULL,
    start_at BIGINT NOT NULL,
    end_at BIGINT NOT NULL,
    break_event_id BIGINT,
    confirmed_at BIGINT,
    source_candle_ids TEXT NOT NULL DEFAULT '[]',
    provenance_status TEXT NOT NULL DEFAULT 'ok'  -- ok | ambiguous
);

CREATE TABLE IF NOT EXISTS ltf_observation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instrument_id BIGINT NOT NULL ,
    zone_id BIGINT NOT NULL ,
    zone_version BIGINT NOT NULL DEFAULT 1,
    cycle_id BIGINT NOT NULL,
    direction TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'waiting_structure',
    activated_at BIGINT NOT NULL,
    data_quality TEXT NOT NULL DEFAULT 'live',
    created_at BIGINT NOT NULL DEFAULT 0,
    updated_at BIGINT NOT NULL DEFAULT 0,
    evidence TEXT NOT NULL DEFAULT '{}',
    UNIQUE (zone_id, cycle_id)
);

CREATE TABLE IF NOT EXISTS ltf_pivot (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instrument_id BIGINT NOT NULL ,
    price DOUBLE PRECISION NOT NULL,
    kind TEXT NOT NULL,                 -- high | low
    pivot_at BIGINT NOT NULL,          -- ms: свеча экстремума
    confirmed_at BIGINT,               -- ms: закрытие i+r; NULL — кандидат
    role TEXT NOT NULL DEFAULT 'none',  -- HH | HL | LH | LL | none
    role_assigned_at BIGINT,
    "left" BIGINT NOT NULL DEFAULT 3,  -- настройки l/r (§5.1)
    "right" BIGINT NOT NULL DEFAULT 3,
    candle_open_time BIGINT NOT NULL,
    state TEXT NOT NULL DEFAULT 'candidate',  -- candidate | confirmed | ambiguous
    calc_version_id BIGINT,            -- версия расчёта (L03)
    superseded_by BIGINT               -- id версии, заменившей опору; NULL — действующая
);

CREATE TABLE IF NOT EXISTS ltf_pivot_role_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pivot_id BIGINT NOT NULL ,
    old_role TEXT,
    new_role TEXT NOT NULL,
    changed_at BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS ltf_plateau (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instrument_id BIGINT NOT NULL ,
    side TEXT NOT NULL,                 -- high | low
    level DOUBLE PRECISION NOT NULL,
    start_open BIGINT NOT NULL,        -- open_time первой свечи группы
    end_open BIGINT NOT NULL,          -- open_time последнего участника
    members_json TEXT NOT NULL DEFAULT '[]',
    revision BIGINT NOT NULL DEFAULT 1,
    state TEXT NOT NULL DEFAULT 'confirmed',  -- confirmed | ambiguous | forming
    confirmed_at BIGINT,
    created_at BIGINT NOT NULL DEFAULT 0,
    UNIQUE (instrument_id, side, level, start_open)
);

CREATE TABLE IF NOT EXISTS ltf_range (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL ,
    version BIGINT NOT NULL,
    lower DOUBLE PRECISION NOT NULL,
    upper DOUBLE PRECISION NOT NULL,
    mid DOUBLE PRECISION NOT NULL,
    anchor_low_pivot_id BIGINT,
    anchor_high_pivot_id BIGINT,
    available_at BIGINT NOT NULL,
    prev_version_id BIGINT,
    -- §5/§12: continuation — диапазон продолжения; origin_reversal —
    -- зарезервировано для следующего этапа; anchor_policy — политика якорей
    kind TEXT NOT NULL DEFAULT 'continuation',
    anchor_policy TEXT,
    structural_epoch_id BIGINT NOT NULL DEFAULT 1,
    UNIQUE (scenario_id, version)
);

CREATE TABLE IF NOT EXISTS ltf_review (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entry_zone_id BIGINT NOT NULL ,
    scenario_id BIGINT,
    decision TEXT NOT NULL,
    author TEXT NOT NULL DEFAULT 'owner',
    text TEXT NOT NULL DEFAULT '',
    created_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS ltf_review_assessment (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entry_zone_id BIGINT NOT NULL ,
    review_id BIGINT NOT NULL ,
    review_decision TEXT NOT NULL,
    geometry_verdict TEXT NOT NULL,      -- valid | invalid | needs_correction | unknown
    lifecycle_verdict TEXT,              -- tested | NULL
    reason_code TEXT NOT NULL DEFAULT '',
    evidence_source TEXT NOT NULL DEFAULT 'manual_ui',
    assessed_as_of BIGINT NOT NULL DEFAULT 0,
    reviewed_at BIGINT NOT NULL DEFAULT 0,
    requires_clarification BIGINT NOT NULL DEFAULT 0,
    corrected_lower DOUBLE PRECISION,
    corrected_upper DOUBLE PRECISION
);

CREATE TABLE IF NOT EXISTS ltf_scenario (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    observation_id BIGINT NOT NULL ,
    direction TEXT NOT NULL,
    "trigger" TEXT NOT NULL,            -- BOS | SMS
    stage TEXT NOT NULL,                -- primary | secondary
    state TEXT NOT NULL DEFAULT 'range_pending',
    trigger_event_id BIGINT,
    cancellation_reason TEXT,
    cancelled_at BIGINT,
    -- §5/§12: причинная цепочка — триггерное событие, движение, эпоха
    origin_break_event_id BIGINT,
    origin_movement_id BIGINT,
    structural_epoch_id BIGINT NOT NULL DEFAULT 1,
    -- §5/§12: уровень отмены как хранимый факт с происхождением (pivot машины)
    reverse_break_level_price DOUBLE PRECISION,
    reverse_break_pivot_id BIGINT,
    reverse_break_confirmed_at BIGINT,
    last_processed_close BIGINT,       -- ms: close_time последней обработанной H1
    -- правила v1 §3/§6.2: причинный HTF-контакт и якорь рабочего PD
    htf_interaction_id BIGINT,
    pd_anchor_structure_key TEXT,
    pd_anchor_kind TEXT,                -- BOS | SMS (равноправны, тип сохраняется)
    created_at BIGINT NOT NULL DEFAULT 0,
    updated_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS ltf_scenario_entry (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL ,
    entry_zone_id BIGINT NOT NULL ,
    range_version BIGINT NOT NULL,
    eligible BIGINT NOT NULL DEFAULT 1,
    overlap TEXT NOT NULL DEFAULT 'none',   -- full | partial | none
    state TEXT NOT NULL DEFAULT 'fresh',    -- fresh | out_of_range | tested | invalid
    -- ТЗ «LTF Current Setup» §10: стабильный код пригодности
    -- (ok | outside_pd | tested_too_deep | type_disabled | invalid |
    --  swept_level | origin_unresolved | range_pending); '' — до миграции
    reason TEXT NOT NULL DEFAULT '',
    added_at BIGINT NOT NULL DEFAULT 0,
    updated_at BIGINT NOT NULL DEFAULT 0,
    UNIQUE (scenario_id, entry_zone_id, range_version)
);

CREATE TABLE IF NOT EXISTS ltf_structure_event (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL ,
    kind TEXT NOT NULL,                 -- BOS | SMS
    stage TEXT NOT NULL,                -- primary | secondary
    direction TEXT NOT NULL,
    break_level DOUBLE PRECISION NOT NULL,
    break_candle_open_time BIGINT NOT NULL,
    occurred_at BIGINT NOT NULL,
    detected_at BIGINT NOT NULL,
    ref_pivot_ids TEXT NOT NULL DEFAULT '[]',
    accompanying BIGINT NOT NULL DEFAULT 0,  -- §6.5: SMS сопутствующий при BOS
    level_key TEXT NOT NULL,            -- стабильный ключ уровня для дедупликации
    evidence TEXT NOT NULL DEFAULT '{}',
    UNIQUE (scenario_id, level_key, stage)
);

CREATE TABLE IF NOT EXISTS market_publication (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, instrument_id BIGINT NOT NULL, event_ids TEXT NOT NULL, created_at BIGINT NOT NULL, published_at BIGINT);

CREATE TABLE IF NOT EXISTS market_transition (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instrument_id BIGINT NOT NULL,
    market_break_key TEXT NOT NULL,
    market_transition_key TEXT NOT NULL,
    direction TEXT NOT NULL,
    break_candle_open_time BIGINT NOT NULL,
    anchor_key TEXT NOT NULL,
    notification_kind TEXT NOT NULL DEFAULT 'market_transition',
    payload TEXT NOT NULL DEFAULT '{}',
    created_at BIGINT NOT NULL,
    UNIQUE(market_break_key, notification_kind)
);

CREATE TABLE IF NOT EXISTS meta (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS notification_fact (
    destination TEXT NOT NULL,
    channel TEXT NOT NULL,
    semantic_key TEXT NOT NULL,
    packet_id BIGINT NOT NULL ,
    PRIMARY KEY(destination,channel,semantic_key)
);

CREATE TABLE IF NOT EXISTS notification_incident (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    venue TEXT NOT NULL,
    reason TEXT NOT NULL,
    started_at BIGINT NOT NULL,
    recovered_at BIGINT,
    packet_id BIGINT 
);

CREATE TABLE IF NOT EXISTS notification_incident_stream (
    incident_id BIGINT NOT NULL ,
    instrument_id BIGINT NOT NULL,
    timeframe TEXT NOT NULL,
    recovered BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY(incident_id,instrument_id,timeframe)
);

CREATE TABLE IF NOT EXISTS notification_member (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    packet_id BIGINT NOT NULL ,
    channel TEXT NOT NULL,
    event_id BIGINT NOT NULL,
    reason TEXT,
    UNIQUE(packet_id,channel,event_id)
);

CREATE TABLE IF NOT EXISTS notification_packet (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    destination TEXT NOT NULL,
    channel TEXT NOT NULL,
    semantic_key TEXT NOT NULL,
    card TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    quiet BIGINT NOT NULL DEFAULT 0,
    created_at BIGINT NOT NULL,
    due_at BIGINT NOT NULL,
    sent_at BIGINT,
    message_id BIGINT,
    photo BIGINT NOT NULL DEFAULT 0,
    attempts BIGINT NOT NULL DEFAULT 0,
    lease_until BIGINT NOT NULL DEFAULT 0,
    dirty BIGINT NOT NULL DEFAULT 0,
    reason TEXT,
    parent_id BIGINT ,
    UNIQUE(destination, channel, semantic_key)
);

CREATE TABLE IF NOT EXISTS pd_revision (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL ,
    range_version BIGINT,
    anchor_structure_key TEXT NOT NULL,
    anchor_kind TEXT NOT NULL,           -- BOS | SMS
    anchors_json TEXT NOT NULL DEFAULT '[]',  -- структурные опоры PD
    available_at BIGINT NOT NULL,
    created_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS quote_spool (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instrument_id BIGINT NOT NULL,
    source TEXT NOT NULL,
    event_at BIGINT,
    received_at BIGINT NOT NULL,
    price DOUBLE PRECISION NOT NULL,
    price_kind TEXT NOT NULL,
    source_seq TEXT,
    created_at BIGINT NOT NULL
, status TEXT NOT NULL DEFAULT 'pending', attempts BIGINT NOT NULL DEFAULT 0, next_attempt_at BIGINT NOT NULL DEFAULT 0, last_error TEXT, processed_at BIGINT, dedup_key TEXT, owner_generation BIGINT);

CREATE TABLE IF NOT EXISTS review (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    zone_id BIGINT NOT NULL ,
    decision TEXT NOT NULL,
    author TEXT NOT NULL DEFAULT 'owner',
    text TEXT NOT NULL DEFAULT '',
    boundary_version BIGINT NOT NULL DEFAULT 1,
    created_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS review_assessment (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    zone_id BIGINT NOT NULL ,
    review_id BIGINT NOT NULL ,
    review_decision TEXT NOT NULL,
    geometry_verdict TEXT NOT NULL,      -- valid | invalid | needs_correction | unknown
    lifecycle_verdict TEXT,              -- completed | converted | NULL
    reason_code TEXT NOT NULL DEFAULT '',
    evidence_source TEXT NOT NULL DEFAULT 'manual_ui',
    assessed_as_of BIGINT NOT NULL DEFAULT 0,
    reviewed_at BIGINT NOT NULL DEFAULT 0,
    requires_clarification BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS schema_version (version BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS visit (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    zone_id BIGINT NOT NULL ,
    cycle_id BIGINT NOT NULL,
    entered_at BIGINT NOT NULL,
    exited_at BIGINT,
    max_depth DOUBLE PRECISION NOT NULL DEFAULT 0,
    observed BIGINT NOT NULL DEFAULT 1,
    exit_kind TEXT,
    extreme DOUBLE PRECISION,                       -- экстремум захода (ТЗ §4)
    d_raw DOUBLE PRECISION                          -- исходная глубина до clamp (ТЗ §4)
);

CREATE TABLE IF NOT EXISTS zone (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    instrument_id BIGINT NOT NULL ,
    type TEXT NOT NULL,
    direction TEXT NOT NULL,
    timeframe TEXT NOT NULL,
    lower DOUBLE PRECISION NOT NULL,
    upper DOUBLE PRECISION NOT NULL,
    formed_at BIGINT NOT NULL,
    confirmed_at BIGINT,
    status TEXT NOT NULL,
    cycle_id BIGINT NOT NULL DEFAULT 1,
    source TEXT NOT NULL DEFAULT 'auto',
    rule_version TEXT NOT NULL DEFAULT '0.2',
    evidence TEXT NOT NULL DEFAULT '{}',
    created_at BIGINT NOT NULL DEFAULT 0,
    -- §15.1.3: границы рисунка на графике и причина завершения
    display_from BIGINT,
    display_until BIGINT,
    end_reason TEXT,
    -- §6/§15.6: состояние машины OB → Breaker
    breakout_close_at BIGINT,
    breaker_forbidden BIGINT NOT NULL DEFAULT 0,
    breakout_expired BIGINT NOT NULL DEFAULT 0,
    -- §15.7: история после подтверждения неполна — нужен replay
    needs_replay BIGINT NOT NULL DEFAULT 0,
    -- ТЗ «Единый движок» (22.09.2026) §3: актуальность отдельно от пригодности
    market_validity TEXT NOT NULL DEFAULT 'active',  -- active | invalid
    max_test_depth DOUBLE PRECISION NOT NULL DEFAULT 0,          -- макс. глубина самостоятельных тестов
    has_tests BIGINT NOT NULL DEFAULT 0,
    entry_eligible BIGINT NOT NULL DEFAULT 1,
    -- ТЗ §7: ручные зоны — выбранное начало на графике и типовое правило
    anchor_time BIGINT,
    zone_type TEXT,
    test_extreme DOUBLE PRECISION                   -- глубочайший экстремум тестов (точные сравнения 90%)
);

CREATE TABLE IF NOT EXISTS zone_activation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    zone_id BIGINT NOT NULL ,
    cycle_id BIGINT NOT NULL,
    episode_id BIGINT,
    observation_id BIGINT,
    started_at BIGINT NOT NULL,
    ended_at BIGINT,
    end_reason TEXT,
    depth_before DOUBLE PRECISION,               -- глубина до независимой активации; NULL — unknown
    fill_before DOUBLE PRECISION,                -- заполнение до активации; NULL — unknown
    max_depth_current DOUBLE PRECISION NOT NULL DEFAULT 0,
    fill_current DOUBLE PRECISION NOT NULL DEFAULT 0,
    fresh_for_new_activation BIGINT NOT NULL DEFAULT 1,
    current_activation_valid BIGINT NOT NULL DEFAULT 1,
    created_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS zone_relation (
    zone_id BIGINT PRIMARY KEY ,
    parent_ob_id BIGINT,
    confirming_fvg_id BIGINT,
    predecessor_ob_id BIGINT,
    visual_group_id BIGINT
);

